import type { ImageName } from "@/content/types"

/** Widths generated by scripts/optimize-images.mjs. */
export const IMAGE_WIDTHS = [640, 1280, 1920] as const
export type ImageWidth = (typeof IMAGE_WIDTHS)[number]

export const imageSrc = (name: ImageName, width: ImageWidth = 1280) => `/images/${name}-${width}.webp`
